using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
using System.Linq;
using System.Windows.Forms;
namespace F1Manager {
public class PodiumCard:Control {
    readonly Career state;readonly Row row;readonly int place;readonly Func<double> progress;
    public PodiumCard(Career career,Row result,int rank,Func<double> animation){state=career;row=result;place=rank;progress=animation;BackColor=Theme.Card;DoubleBuffered=true;}
    protected override void OnPaint(PaintEventArgs e){double reveal=progress();using(var background=new SolidBrush(Theme.Card))e.Graphics.FillRectangle(background,ClientRectangle);if(reveal<=0)return;if(reveal>=1){DrawCard(e.Graphics,reveal);return;}using(var frame=new Bitmap(Width,Height)){using(var canvas=Graphics.FromImage(frame)){canvas.Clear(Theme.Card);DrawCard(canvas,reveal);}var matrix=new ColorMatrix();matrix.Matrix33=(float)reveal;using(var attributes=new ImageAttributes()){attributes.SetColorMatrix(matrix);e.Graphics.DrawImage(frame,ClientRectangle,0,0,Width,Height,GraphicsUnit.Pixel,attributes);}}}
    void DrawCard(Graphics g,double reveal){g.SmoothingMode=SmoothingMode.AntiAlias;Color accent=place==1?Color.FromArgb(235,190,78):place==2?Color.FromArgb(198,201,208):Color.FromArgb(203,143,106);int rise=(int)((1-reveal)*24);var area=new Rectangle(1,rise,Width-3,Height-rise-2);using(var path=Theme.Round(area,16))using(var b=new SolidBrush(Color.FromArgb(29,29,29)))using(var pen=new Pen(Color.FromArgb(95,accent))){g.FillPath(b,path);g.DrawPath(pen,path);}if(row==null){DrawCaption(g,"Нет финишировавшего участника",new Rectangle(20,180,Width-40,70),14,Theme.Muted);return;}var person=Engine.Person(state,row.Id);Color team=ColorTranslator.FromHtml(Engine.Team(state,row.Team).Color);var photoArea=new Rectangle(16,67+rise,Width-32,183);using(var path=Theme.Round(photoArea,12))using(var gradient=new LinearGradientBrush(photoArea,Theme.Mix(Color.FromArgb(24,24,24),team,.23),Color.FromArgb(19,19,19),90f)){g.FillPath(gradient,path);var saved=g.Save();g.SetClip(path,CombineMode.Intersect);using(var stripe=new Pen(Color.FromArgb(40,team),22))g.DrawLine(stripe,15,photoArea.Bottom,Width-40,photoArea.Top);Theme.ImageFit(g,DriverPhotos.Get(person),new Rectangle(Width/2-78,68+rise,156,192));using(var fade=new LinearGradientBrush(new Rectangle(16,225+rise,Width-32,26),Color.FromArgb(0,26,26,26),Color.FromArgb(255,26,26,26),90f))g.FillRectangle(fade,16,225+rise,Width-32,26);g.Restore(saved);}
        using(var platform=Theme.Round(new Rectangle(16,247+rise,Width-32,103),10))using(var b=new SolidBrush(Theme.Mix(Color.FromArgb(26,26,26),accent,.08)))g.FillPath(b,platform);using(var pen=new Pen(accent,2))g.DrawLine(pen,29,249+rise,Width-29,249+rise);DrawCaption(g,place.ToString("00"),new Rectangle(20,14+rise,70,44),34,accent,true);using(var logo=Theme.Round(new Rectangle(Width-71,15+rise,52,42),8))g.FillPath(Brushes.White,logo);Theme.ImageFit(g,TeamLogos.Get(row.Team),new Rectangle(Width-67,19+rise,44,34));DrawCaption(g,person.Name,new Rectangle(18,261+rise,Width-36,29),19,Color.White,true);DrawCaption(g,Engine.Team(state,row.Team).Name,new Rectangle(18,293+rise,Width-36,23),12,Theme.Muted);DrawCaption(g,row.Points>0?row.Points+" очков":ManagerForm.LapFormat(row.Time),new Rectangle(18,323+rise,Width-36,24),15,accent,true);
    }
    static void DrawCaption(Graphics g,string text,Rectangle r,int size,Color color,bool bold=false){using(var font=new Font("Segoe UI",size,bold?FontStyle.Bold:FontStyle.Regular,GraphicsUnit.Pixel))using(var brush=new SolidBrush(color))using(var format=new StringFormat{Alignment=StringAlignment.Center,LineAlignment=StringAlignment.Center,Trimming=StringTrimming.EllipsisCharacter})g.DrawString(text,font,brush,r,format);}

}
public class PodiumOverlay:GameOverlay {
    internal readonly SoftButton ContinueButton=new SoftButton{Text="Продолжить",Primary=true};
    public event Action Continued;
    readonly PodiumCard[] cards=new PodiumCard[3];
    internal readonly string SessionName;internal readonly Row[] Winners;
    protected override Size SheetSize {get{return new Size(1040,650);}}
    public PodiumOverlay(Career state,SessionResult result,int round,int year,bool animated):base(animated){SessionName=result.Name;bool qualifying=result.Name.StartsWith("Q")||result.Name.StartsWith("SQ");Winners=result.Rows.Where(r=>!r.Dnf&&(qualifying?r.Best>0&&r.Best<99999:r.Time>0)).OrderBy(r=>r.Position).Take(3).ToArray();string title=qualifying?(result.Name.EndsWith("3")?"ПОУЛ-ПОЗИШН":"ЛИДЕРЫ "+result.Name):result.Name=="Спринт"?"ПОДИУМ СПРИНТА":"ПОДИУМ ГРАН-ПРИ";LabelAt(Sheet,title,32,22,970,43,29,true,Color.White);LabelAt(Sheet,year+"  /  "+Data.Tracks[round].Country+"  /  "+result.Name,34,76,965,28,14);if(Winners.Length==0)LabelAt(Sheet,qualifying?"Никто не установил время. Полные результаты сохранены.":"Ни один пилот не финишировал. Результаты сходов сохранены.",32,119,965,36,14,false,Theme.Red);int[] order={2,1,3};for(int i=0;i<3;i++){int rank=order[i];var winner=Winners.Length>=rank?Winners[rank-1]:null;cards[i]=new PodiumCard(state,winner,rank,()=>Animated?Theme.Ease((Clock.Elapsed.TotalSeconds-(rank==3?.22:rank==2?.65:1.08))/.38):1);Sheet.Controls.Add(cards[i]);}Sheet.Controls.Add(ContinueButton);ContinueButton.Click+=(o,e)=>Cancel();Sheet.Resize+=(o,e)=>LayoutCards();LayoutCards();}
    void LayoutCards(){int w=(Sheet.Width-88)/3;for(int i=0;i<3;i++)if(cards[i]!=null)cards[i].Bounds=new Rectangle(32+i*(w+12),i==1?145:167,w,366);ContinueButton.Bounds=new Rectangle(Sheet.Width-302,Sheet.Height-64,270,43);}
    protected override void Advance(){foreach(var c in cards)c.Invalidate();}
    public override void Cancel(){if(!Closing&&Continued!=null)Continued();}
}
public class EngineeringOverlay:GameOverlay {
    internal readonly SoftButton ContinueButton=new SoftButton{Text="Вернуться к команде",Primary=true};
    public event Action Continued;public event Action<int> Browse;
    public EngineeringReport Report;readonly Panel upgrades=new Panel{AutoScroll=true,BackColor=Theme.Card};
    protected override Size SheetSize {get{return new Size(1040,650);}}
    public EngineeringOverlay(Career state,EngineeringReport report,int index,bool animated):base(animated){Report=report;LabelAt(Sheet,"ИНЖЕНЕРНЫЙ ОТЧЁТ",32,21,970,40,27,true,Color.White);LabelAt(Sheet,report.Year+" / "+report.Track+" / Этап "+(report.Round+1),33,68,970,27,14);LabelAt(Sheet,"Болид на трассе: P"+report.OverallRank+" из "+state.Teams.Count+"  •  "+report.Layout,33,103,970,29,14,true,Theme.Red);for(int i=0;i<10;i++){int col=i/5,row=i%5,x=32+col*494,y=148+row*37;LabelAt(Sheet,CarModel.Names[i],x,y,270,29,13);LabelAt(Sheet,report.Values[i].ToString("0.0")+"  "+report.Change[i].ToString("+0.00;-0.00;—"),x+269,y,139,29,13,true,Color.White);LabelAt(Sheet,"P"+report.Ranks[i],x+414,y,60,29,14,true,Theme.Red);}LabelAt(Sheet,"ПРОВЕРКА НОВИНОК",33,346,970,28,13,true,Color.White);upgrades.Bounds=new Rectangle(32,383,976,170);Sheet.Controls.Add(upgrades);if(report.Upgrades.Count==0)LabelAt(upgrades,"Новых деталей для проверки нет. Выше — состояние болида и изменения с прошлого отчёта.",12,12,920,65,14);int top=0;foreach(var trial in report.Upgrades){var part=Data.Parts.First(p=>p.Key==trial.Key);var card=new RoundedPanel{BackColor=Color.FromArgb(31,31,31),Bounds=new Rectangle(0,top,948,94)};card.Controls.Add(new PartPicture(trial.Key){Bounds=new Rectangle(10,13,100,65)});LabelAt(card,part.Name+(trial.Version>0?" v"+trial.Version:""),122,9,520,25,16,true,Color.White);LabelAt(card,trial.Status,635,11,296,45,13,true,trial.ActualGain<=.01?Color.FromArgb(255,111,117):Color.FromArgb(96,219,164));LabelAt(card,trial.BenchFailed?"Стендовые испытания провалены. Деталь не использовалась в заезде.":"Эффективность: "+(100*trial.ActualGain/Math.Max(.001,trial.ExpectedGain)).ToString("0")+"% от расчёта  •  "+string.Join("  /  ",Enumerable.Range(0,10).Where(i=>Math.Abs(trial.Delta[i])>.001).Take(3).Select(i=>CarModel.Names[i]+" "+trial.Delta[i].ToString("+0.00;-0.00;0"))),122,42,803,44,12);upgrades.Controls.Add(card);top+=103;}var previous=new SoftButton{Text="‹ Прошлый",Bounds=new Rectangle(32,586,160,43),Enabled=index>0};var next=new SoftButton{Text="Следующий ›",Bounds=new Rectangle(207,586,160,43),Enabled=index<state.EngineeringReports.Count-1};previous.Click+=(o,e)=>{if(Browse!=null)Browse(-1);};next.Click+=(o,e)=>{if(Browse!=null)Browse(1);};Sheet.Controls.Add(previous);Sheet.Controls.Add(next);ContinueButton.Bounds=new Rectangle(718,586,290,43);Sheet.Controls.Add(ContinueButton);ContinueButton.Click+=(o,e)=>Cancel();}
    public override void Cancel(){if(!Closing&&Continued!=null)Continued();}
}
public partial class ManagerForm {
    void PresentSession(string name,int round,int year){bool qualify=name.StartsWith("Q")||name.StartsWith("SQ");if(!qualify&&name!="Гонка"&&name!="Спринт"){Notify(name+": результаты готовы.");return;}var result=name=="Гонка"?State.Archive.Last().Sessions.Last():State.Weekend.Results.Last();var podium=new PodiumOverlay(State,result,round,year,Preferences.Animations);podium.Continued+=()=>CloseOverlay(()=>{if(name=="Гонка"&&State.EngineeringReports.Count>0)ShowEngineeringReport(State.EngineeringReports.Last());});ShowOverlay(podium);}
    internal void ShowEngineeringReport(EngineeringReport report){if(activeOverlay!=null)return;int index=State.EngineeringReports.IndexOf(report);var overlay=new EngineeringOverlay(State,report,index,Preferences.Animations);overlay.Continued+=()=>CloseOverlay(()=>Go(State.SeasonDone?"hall":"calendar"));overlay.Browse+=direction=>CloseOverlay(()=>ShowEngineeringReport(State.EngineeringReports[index+direction]));ShowOverlay(overlay);}
}
}
